#include <stdio.h>
#include <stdbool.h>
#include <math.h>

static bool search24(const double *nums, int n) {
    if (n == 1) return fabs(nums[0] - 24.0) < 1e-9;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            double a = nums[i], b = nums[j];
            double rest[4];
            int m = 0;
            for (int k = 0; k < n; ++k) if (k != i && k != j) rest[m++] = nums[k];
            double candidates[6];
            int count = 0;
            candidates[count++] = a + b;
            candidates[count++] = a - b;
            candidates[count++] = b - a;
            candidates[count++] = a * b;
            if (fabs(b) > 1e-12) candidates[count++] = a / b;
            if (fabs(a) > 1e-12) candidates[count++] = b / a;
            for (int c = 0; c < count; ++c) {
                rest[m] = candidates[c];
                if (search24(rest, m + 1)) return true;
            }
        }
    }
    return false;
}

bool judgePoint24(int *cards, int cardsSize) {
    double nums[4];
    for (int i = 0; i < cardsSize; ++i) nums[i] = cards[i];
    return search24(nums, cardsSize);
}

