        for (int i = 0; i < (int)a.size(); ++i) {
            for (int j = i + 1; j < (int)a.size(); ++j) {
                double x = a[i], y = a[j];
                vector<double> rest;
                for (int k = 0; k < (int)a.size(); ++k) if (k != i && k != j) rest.push_back(a[k]);
                vector<double> candidates = {x + y, x - y, y - x, x * y};
                if (fabs(y) > 1e-12) candidates.push_back(x / y);
                if (fabs(x) > 1e-12) candidates.push_back(y / x);
                for (double v : candidates) {
                    rest.push_back(v);
                    if (search24(rest)) return true;
                    rest.pop_back();
                }
            }
        }
        return false;
    }
