class Solution {
    public boolean judgePoint24(int[] cards) {
        List<Double> nums = new ArrayList<>();
        for (int x : cards) nums.add((double) x);
        return search(nums);
    }

    private boolean search(List<Double> values) {
        if (values.size() == 1) return Math.abs(values.get(0) - 24.0) < 1e-9;
        for (int i = 0; i < values.size(); i++) {
            for (int j = i + 1; j < values.size(); j++) {
                double a = values.get(i), b = values.get(j);
                List<Double> rest = new ArrayList<>();
                for (int k = 0; k < values.size(); k++) if (k != i && k != j) rest.add(values.get(k));
                List<Double> candidates = new ArrayList<>(Arrays.asList(a + b, a - b, b - a, a * b));
                if (Math.abs(b) > 1e-12) candidates.add(a / b);
                if (Math.abs(a) > 1e-12) candidates.add(b / a);
                for (double v : candidates) {
                    rest.add(v);
                    if (search(rest)) return true;
                    rest.remove(rest.size() - 1);
                }
            }
        }
        return false;
    }
}

